package ru.neverland.townyarmy.tactics;
import java.util.*;import java.util.concurrent.*;import java.util.function.*;
import org.bukkit.*;import org.bukkit.command.CommandSender;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.inventory.*;import org.bukkit.inventory.*;
import ru.neverland.core.*;import ru.neverland.townyarmy.*;
import static ru.neverland.townyarmy.tactics.TacticsBook.*;

/** Every click rechecks the current town, authority, revision and frozen quote. */
public final class TacticsMenus implements Listener {
 private final TacticsService service;
 @FunctionalInterface interface Action{void run(Player p)throws Exception;}
 private static final class Page implements InventoryHolder {final UUID viewer;final Map<Integer,Action> actions=new HashMap<>();Inventory inventory;Page(UUID viewer){this.viewer=viewer;}public Inventory getInventory(){return inventory;}}
 public TacticsMenus(TacticsService service){this.service=service;}
 private Page page(Player p,String title,Inventory previous){var h=new Page(p.getUniqueId());h.inventory=MenuStyle.inventory(service.plugin,h,54,title);button(h,45,Material.ARROW,"Назад",List.of("Вернуться в предыдущее меню"),who->MenuStyle.returnTo(who,previous));return h;}
 private void button(Page h,int slot,Material material,String title,List<String> lore,Action action){var item=new ItemStack(material);var meta=item.getItemMeta();meta.displayName(MenuStyle.nameComponent(MenuStyle.decode(title)));meta.lore(MenuStyle.loreComponents(lore.stream().map(MenuStyle::decode).toList()));meta.addItemFlags(ItemFlag.HIDE_ATTRIBUTES);item.setItemMeta(meta);h.inventory.setItem(slot,item);if(action!=null)h.actions.put(slot,action);}
 private static void say(CommandSender p,String message){p.sendMessage(MenuStyle.decode("&a[Армия] &f"+message));}
 private UUID town(Player p){if(!p.hasPermission("neverlandtownyarmy.use"))throw new IllegalArgumentException("Нет доступа к армии");return service.army.ownTown(p).getUUID();}
 private boolean command(Player p,UUID town){return service.army.officer(p,town,ArmyModel.Rank.LIEUTENANT);}
 private <T>void finish(Player player,CompletionStage<T> receipt,String message,Action reopen){var original=player.getOpenInventory().getTopInventory();say(player,"Сохраняем изменение…");receipt.whenComplete((v,error)->{if(!service.plugin.isEnabled())return;SuiteScheduler.player(service.plugin,player,p->{if(error!=null){Throwable cause=error;while(cause.getCause()!=null)cause=cause.getCause();say(p,"&c"+cause.getMessage());return;}say(p,"&a"+message);if(reopen!=null&&p.getOpenInventory().getTopInventory()==original)try{reopen.run(p);}catch(Exception ex){say(p,"Откройте раздел армии заново.");}});});}
 public void open(Player p,Inventory previous){try(var guard=SuiteState.guard()){
  UUID town=town(p);var h=page(p,"Армия • Специальности и приказы",previous);if(!service.available()){button(h,22,Material.BARRIER,"Этот раздел временно недоступен",List.of("Состав, звания и запасы армии сохранены.","Обратитесь к администратору."),null);p.openInventory(h.inventory);return;}
  Role role=service.role(town,p.getUniqueId());button(h,11,Material.valueOf(role.icon()),"Моя специальность: "+role.title(),List.of("Специальность назначает командование.","Она определяет состав полевого комплекта.","Звание и подразделение сохраняются."),who->roles(who,who.getUniqueId(),h.inventory));
  button(h,15,Material.CHEST,"Получить полевой комплект",List.of("Только после присяги, на военной базе.","Комплект оплачивается военными запасами.","Лимит: "+service.settings.kitsPerDay()+" за 24 часа.","Перед выдачей вы увидите состав и цену."),who->kit(who,h.inventory));
  button(h,29,Material.FILLED_MAP,"Приказы и точка сбора",List.of("Получить задачу и отметить прибытие.","Завершение подтверждает командир.","За отмену и истечение срока штрафа нет."),who->orders(who,0,h.inventory));
  if(command(p,town))button(h,33,Material.WRITABLE_BOOK,"Командование",List.of("/army specialty <игрок> <специальность>","/army order <rally|attack|defend|supply>","<all|подразделение> <описание>","Точка приказа — место вашего персонажа."),who->history(who,0,h.inventory));
  var pending=service.state().pending(p.getUniqueId());if(pending.isPresent())button(h,40,Material.CLOCK,"Незавершённая выдача",List.of(phase(pending.get().phase()),"Повторная выдача заблокирована.","Нажмите: проверить сохранённую квитанцию."),who->kit(who,h.inventory));p.openInventory(h.inventory);
 }}
 public void roles(Player p,UUID target,Inventory previous){try(var guard=SuiteState.guard()){
  UUID town=town(p);var soldier=service.army.repository().state().soldiers().get(target);if(soldier==null||!soldier.town().equals(town))throw new IllegalArgumentException("Боец не найден в вашем городе");var h=page(p,"Специальность • "+ArmyMenu.name(target),previous);int slot=19;for(Role role:Role.values()){var lines=new ArrayList<String>();lines.add(role==service.role(town,target)?"Назначена сейчас":"");lines.add(switch(role){case SOLDIER->"Обычное снаряжение для боя.";case SAPPER->"TNT и инструменты для осады.";case MEDIC->"Лечебные зелья и еда.";case SUPPLIER->"Запас еды и стрел для отряда.";});boolean allowed=service.army.officer(p,town,ArmyModel.Rank.CAPTAIN);lines.add(allowed?"Нажмите: назначить специальность.":"Изменить может командование армии.");button(h,slot,Material.valueOf(role.icon()),role.title(),lines,allowed?who->finish(who,service.assign(who,target,role),"Специальность сохранена.",again->roles(again,target,previous)):null);slot+=2;}p.openInventory(h.inventory);
 }}
 public void kit(Player p,Inventory previous){try(var guard=SuiteState.guard()){
  UUID town=town(p);if(!service.available())throw new IllegalArgumentException("Выдача комплектов временно недоступна");var h=page(p,"Армия • Полевой комплект",previous);var pending=service.state().pending(p.getUniqueId());
  if(pending.isPresent()){var k=pending.get();button(h,13,Material.PAPER,"Квитанция: "+k.id(),List.of("Получатель: "+ArmyMenu.name(k.player()),phase(k.phase()),k.reason(),"Повторная выдача не выполняется."),null);if(k.phase()==KitPhase.REVIEW||k.phase()==KitPhase.ARMED)button(h,31,Material.CLOCK,"Проверить сохранение игрока",List.of("Если сохранённая квитанция найдена,","выдача будет подтверждена без новых предметов.","Если её нет — обратитесь к администратору."),who->{var future=service.reconcile(who,k.id());future.whenComplete((found,error)->{if(error==null&&!found)SuiteScheduler.player(service.plugin,who,x->say(x,"Квитанция не найдена. Нужна ручная сверка администратора: "+k.id()));});finish(who,future,"Проверка завершена.",again->kit(again,previous));});p.openInventory(h.inventory);return;}
  Role role=service.role(town,p.getUniqueId());var frozen=service.settings();long shown=System.currentTimeMillis();var kit=frozen.loadouts().get(role);var description=new ArrayList<String>();description.add("Специальность: "+role.title());description.add("Комплект:");for(var e:new TreeMap<>(kit.items()).entrySet())description.add("• "+itemName(e.getKey())+" × "+e.getValue());description.add("Стоимость из военных запасов:");for(var e:new TreeMap<>(kit.cost()).entrySet())description.add("• "+resource(e.getKey())+": "+ArmyMenu.amount(e.getValue()));description.add("Не чаще раза в "+frozen.kitCooldown()/60000+" мин.");description.add("Не более "+frozen.kitsPerDay()+" комплектов за 24 часа.");description.add("Нужно место для всего комплекта и присяга.");description.add("Получение доступно только на базе города.");button(h,13,Material.CHEST,role.title()+": состав и стоимость",description,null);
  button(h,29,Material.LIME_DYE,"Оплатить запасами и получить",List.of("После подтверждения из военного склада","будет списана указанная стоимость."),who->{if(System.currentTimeMillis()-shown>60000||!town(who).equals(town)||!service.settings().equals(frozen)||service.role(town,who.getUniqueId())!=role)throw new IllegalArgumentException("Условия изменились или окно устарело. Откройте комплект заново");finish(who,service.requestKit(who),"Комплект выдан и сохранён.",again->kit(again,previous));});button(h,33,Material.RED_DYE,"Отмена",List.of("Закрыть без списания запасов"),who->MenuStyle.returnTo(who,previous));p.openInventory(h.inventory);
 }}
 public void orders(Player p,int requested,Inventory previous){try(var guard=SuiteState.guard()){
  UUID town=town(p);if(!service.army.officer(p,town,ArmyModel.Rank.RECRUIT))throw new IllegalArgumentException("Приказы доступны военнослужащим после присяги");var all=service.state().orders().values().stream().filter(o->o.town().equals(town)).sorted(Comparator.comparingLong(Order::created).reversed()).toList();int page=Math.max(0,Math.min(requested,Math.max(0,(all.size()-1)/36)));var h=page(p,"Армия • Приказы",previous);for(int i=page*36;i<Math.min(all.size(),(page+1)*36);i++){var o=all.get(i);button(h,i%36,Material.FILLED_MAP,o.task().title()+": "+o.description(),List.of(orderPhase(o),"Приняли: "+o.accepted().size()+"; прибыли: "+o.arrived().size(),"Нажмите: точка и действия"),who->order(who,o.id(),h.inventory));}if(page>0)button(h,48,Material.ARROW,"Предыдущие",List.of(),who->orders(who,page-1,previous));if((page+1)*36<all.size())button(h,50,Material.ARROW,"Следующие",List.of(),who->orders(who,page+1,previous));p.openInventory(h.inventory);
 }}
 private void order(Player p,UUID id,Inventory previous){try(var guard=SuiteState.guard()){
  UUID town=town(p);if(!service.army.officer(p,town,ArmyModel.Rank.RECRUIT))throw new IllegalArgumentException("Приказы доступны после присяги");var o=service.state().orders().get(id);if(o==null||!o.town().equals(town))throw new IllegalArgumentException("Приказ не найден");var h=page(p,"Приказ • "+o.task().title(),previous);var world=Bukkit.getWorld(o.point().world());button(h,13,Material.MAP,o.description(),List.of(orderPhase(o),"Мир: "+(world==null?"недоступен":world.getName()),"Точка: "+Math.round(o.point().x())+", "+Math.round(o.point().y())+", "+Math.round(o.point().z()),"Для прибытия: не дальше "+o.radius()+" блоков.","Подразделение: "+unit(o.unit()),"Приняли: "+o.accepted().size()+"; прибыли: "+o.arrived().size(),"Отметка прибытия не означает победу в бою."),null);
  if(o.phase()==OrderPhase.OPEN&&o.expires()>System.currentTimeMillis()){button(h,28,Material.WRITABLE_BOOK,"Подтвердить получение",List.of("Сообщить командиру, что задача понятна"),who->finish(who,service.mark(who,id,o.revision(),false),"Получение приказа подтверждено.",again->order(again,id,previous)));button(h,30,Material.COMPASS,"Я прибыл к точке",List.of("Проверяется ваше фактическое положение"),who->finish(who,service.mark(who,id,o.revision(),true),"Прибытие подтверждено.",again->order(again,id,previous)));if(command(p,town)){button(h,32,Material.LIME_DYE,"Задача выполнена",List.of("Отметка командования; награды не начисляются"),who->finish(who,service.closeOrder(who,id,o.revision(),true),"Приказ завершён.",again->orders(again,0,previous)));button(h,34,Material.RED_DYE,"Отменить приказ",List.of("Закрыть без штрафов"),who->finish(who,service.closeOrder(who,id,o.revision(),false),"Приказ отменён.",again->orders(again,0,previous)));}}p.openInventory(h.inventory);
 }}
 private void history(Player p,int requested,Inventory previous){try(var guard=SuiteState.guard()){
  UUID town=town(p);if(!command(p,town))throw new IllegalArgumentException("Журнал доступен командованию");var all=new ArrayList<>(service.state().history().stream().filter(e->e.town().equals(town)).toList());Collections.reverse(all);int page=Math.max(0,Math.min(requested,Math.max(0,(all.size()-1)/36)));var h=page(p,"Армия • Специальности и выдачи",previous);for(int i=page*36;i<Math.min(all.size(),(page+1)*36);i++){var e=all.get(i);button(h,i%36,Material.PAPER,e.reason(),List.of("Автор: "+ArmyMenu.name(e.actor()),"Боец: "+ArmyMenu.name(e.subject()),"Операция: "+e.operation()),null);}if(page>0)button(h,48,Material.ARROW,"Предыдущие",List.of(),who->history(who,page-1,previous));if((page+1)*36<all.size())button(h,50,Material.ARROW,"Следующие",List.of(),who->history(who,page+1,previous));p.openInventory(h.inventory);
 }}
 private void review(Player p,UUID id,boolean delivered,String reason){try(var guard=SuiteState.guard()){
  if(!p.hasPermission("neverlandtownyarmy.admin"))throw new IllegalArgumentException("Нет административных прав");var k=service.state().kits().get(id);if(k==null)throw new IllegalArgumentException("Квитанция не найдена");long at=System.currentTimeMillis();var h=page(p,"Сверка военного комплекта",MenuStyle.previousMenu(p));button(h,13,Material.PAPER,"Подтвердите результат проверки",List.of("Квитанция: "+id,"Получатель: "+ArmyMenu.name(k.player()),"Комплект: "+k.role().title(),delivered?"Предметы были получены. Новая выдача не нужна.":"Предметы не были получены. Вернуть стоимость в запас.","Причина: "+reason),null);button(h,29,Material.LIME_DYE,"Подтвердить сверку",List.of("Решение и автор попадут в журнал администрации"),who->{if(System.currentTimeMillis()-at>60000)throw new IllegalArgumentException("Подтверждение устарело");finish(who,service.adminResolve(who,id,k.phaseAt(),delivered,reason),"Результат проверки сохранён.",null);});p.openInventory(h.inventory);
 }}
 public boolean command(CommandSender sender,String[] args)throws Exception{if(args.length==0||!Set.of("tactics","specialty","orders","order","kit","kitreview").contains(args[0].toLowerCase(Locale.ROOT)))return false;if(!(sender instanceof Player p))throw new IllegalArgumentException("Откройте армейский раздел в игре");switch(args[0].toLowerCase(Locale.ROOT)){
  case "tactics"->{if(args.length!=1)throw new IllegalArgumentException("/army tactics");open(p,MenuStyle.previousMenu(p));}
  case "specialty"->{if(args.length<2||args.length>3)throw new IllegalArgumentException("/army specialty <игрок> [soldier|sapper|medic|supplier]");var resident=com.palmergames.bukkit.towny.TownyAPI.getInstance().getResident(args[1]);if(resident==null)throw new IllegalArgumentException("Игрок не найден");if(args.length==2)roles(p,resident.getUUID(),MenuStyle.previousMenu(p));else finish(p,service.assign(p,resident.getUUID(),Role.parse(args[2])),"Специальность назначена.",null);}
  case "orders"->{if(args.length!=1)throw new IllegalArgumentException("/army orders");orders(p,0,MenuStyle.previousMenu(p));}
  case "order"->{if(args.length<4)throw new IllegalArgumentException("/army order <rally|attack|defend|supply> <all|infantry|cavalry|navy|air> <описание>");finish(p,service.createOrder(p,Task.valueOf(args[1].toUpperCase(Locale.ROOT)),args[2].toLowerCase(Locale.ROOT),String.join(" ",Arrays.copyOfRange(args,3,args.length))),"Приказ сохранён. Точка — ваше текущее положение.",null);}
  case "kit"->{if(args.length!=1)throw new IllegalArgumentException("/army kit");kit(p,MenuStyle.previousMenu(p));}
  case "kitreview"->{if(args.length<4||!Set.of("delivered","return").contains(args[2]))throw new IllegalArgumentException("/army kitreview <UUID> <delivered|return> <причина>");review(p,UUID.fromString(args[1]),args[2].equals("delivered"),ArmyModel.reason(String.join(" ",Arrays.copyOfRange(args,3,args.length))));}
 }return true;}
 static String phase(KitPhase phase){return switch(phase){case PLANNED->"Ожидает выделения запасов";case FUNDED->"Запасы выделены, выдача готовится";case ARMED,REVIEW->"Нужна сверка сохранения игрока";case COMPLETE->"Выдано и сохранено";case CANCEL_PENDING->"Ожидает полного возврата запасов";case CANCELLED->"Отменено, стоимость возвращена";};}
 static String orderPhase(Order o){if(o.phase()==OrderPhase.OPEN)return "Осталось: "+Math.max(0,(o.expires()-System.currentTimeMillis()+59999)/60000)+" мин.";return switch(o.phase()){case COMPLETED->"Командир подтвердил выполнение";case CANCELLED->"Отменён без штрафа";case EXPIRED->"Срок истёк, штрафа нет";default->"Действует";};}
 static String unit(String s){return switch(s){case "infantry"->"Пехота";case "cavalry"->"Конница";case "navy"->"Флот";case "air"->"Воздушные войска";default->"Все подразделения";};}
 static String resource(String s){return Map.of("metal","Металл","materials","Материалы","wood","Древесина","stone","Камень","food","Еда","water","Вода","knowledge","Знания","influence","Влияние").getOrDefault(s,s);}
 static String itemName(String s){return switch(s){case "SPLASH_POTION_HEALING"->"Взрывное зелье лечения";case "IRON_SWORD"->"Железный меч";case "IRON_HELMET"->"Железный шлем";case "IRON_CHESTPLATE"->"Железный нагрудник";case "SHIELD"->"Щит";case "BREAD"->"Хлеб";case "IRON_PICKAXE"->"Железная кирка";case "FLINT_AND_STEEL"->"Огниво";case "TNT"->"Динамит";case "ARROW"->"Стрелы";default->s;};}
 @EventHandler public void click(InventoryClickEvent event){if(!(event.getView().getTopInventory().getHolder() instanceof Page page))return;event.setCancelled(true);if(!(event.getWhoClicked() instanceof Player player)||!page.viewer.equals(player.getUniqueId()))return;try(var guard=SuiteState.guard()){if(SuiteState.frozen(service.plugin.getName()))return;var action=page.actions.get(event.getRawSlot());if(action==null)return;try{action.run(player);}catch(Exception error){say(player,"&c"+error.getMessage());}}}
 @EventHandler public void drag(InventoryDragEvent event){if(event.getView().getTopInventory().getHolder() instanceof Page)event.setCancelled(true);}
}
